'use strict';
let currency='GBP';try{currency=localStorage.getItem('bep-currency')==='EUR'?'EUR':'GBP'}catch{}
function renderLanding(){const idx={vi:0,en:1,fr:2,de:3}[I18n.language]??1,t=k=>WorkspaceLabels[k][idx];document.getElementById('landing').innerHTML=`<header class="topbar"><a class="brand" href="./"><img src="assets/icon-192.png" alt="" width="38" height="38"><span>bếp<span>finance</span></span></a><div class="top-actions"><select id="language" aria-label="Language">${Object.entries(I18n.languages).map(([code,l])=>`<option value="${code}" ${code===I18n.language?'selected':''}>${l.name}</option>`).join('')}</select><select id="currency" aria-label="${t('currency')}"><option value="GBP" ${currency==='GBP'?'selected':''}>GBP · £</option><option value="EUR" ${currency==='EUR'?'selected':''}>EUR · €</option></select></div></header><main class="landing-main"><section class="landing-hero"><div><span class="eyebrow">BẾP FINANCE / GBP · EUR</span><h1>${t('roleIntro')}</h1><p>${t('intro')}</p><span class="region-chip">${currency==='GBP'?'UK · GBP £':'EU · EUR €'}</span></div><img src="assets/bep-nho.webp" alt="Bếp Nhỏ" width="260" height="260"></section><div class="landing-roles">${['cashier','manager','owner'].map((r,i)=>`<a href="workspace/?role=${r}&currency=${currency}"><span class="role-number">0${i+1}</span><h2>${t(r)}</h2><p>${t(r+'Desc')}</p><b>${t('preview')} →</b><small>${t('login')}</small></a>`).join('')}</div><p class="landing-note">${t('demo')}<br>${t('currencyHint')}<br>${t('backendRequired')}</p></main>`;document.getElementById('language').onchange=e=>I18n.setLanguage(e.target.value);document.getElementById('currency').onchange=e=>{currency=e.target.value;try{localStorage.setItem('bep-currency',currency)}catch{}renderLanding()}}
window.addEventListener('bep:languagechange',renderLanding);renderLanding();
